using System;using System.Collections.Generic;using UnityEngine;
namespace Blocklands
{
    [Serializable] public class InstalledCamera {public int id,region;public bool realm;public Vector3 position,forward,normal;}
    public class CameraFixture:MonoBehaviour {public InstalledCamera Data;}
    public partial class Sandbox
    {
        public readonly List<InstalledCamera> InstalledCameras=new List<InstalledCamera>();int cameraKitVersion;Transform installedCameraRoot;
        public void RestoreCameraKit(SavedWorld s){InstalledCameras.Clear();if(s.installedCameras!=null)InstalledCameras.AddRange(s.installedCameras);cameraKitVersion=s.cameraKitVersion;if(cameraKitVersion<1){Inventory[94]=Mathf.Max(Inventory[94],3);cameraKitVersion=1;}}
        public void EnsureCameraKit(){if(cameraKitVersion>=1)return;Inventory[94]=Mathf.Max(Inventory[94],3);cameraKitVersion=1;}
        public int CameraKitVersion=>cameraKitVersion;
        public bool TakeCameraFromBag(){EnsureCameraKit();if(Inventory[94]<=0){Notice="摄像头用完了：横排铁锭、透明水晶、水晶灯合成。";return false;}SelectItem(94);if(Paused){inventoryOpen=false;SetPaused(false);}Notice="摄像头已拿在手里。看着墙或地面，鼠标右键安装；显示屏会自动增加这个镜头。";return true;}
        public bool InstallCameraFromView(){if(!RayFromView(out var hit,6)){Notice="先看着6米内的墙、地面或平台，再右键安装。";return false;}if(hit.collider.GetComponentInParent<FirstPerson>()!=null||hit.collider.GetComponentInParent<Villager>()!=null||hit.collider.GetComponentInParent<SkyResidentInfo>()!=null||hit.collider.GetComponentInParent<NpcNavigation>()!=null){Notice="摄像头不能安装在人身上，请看墙或地面。";return false;}return InstallCamera(hit.point+hit.normal*.14f,Player.View.transform.forward,hit.normal);}
        public bool InstallCamera(Vector3 p,Vector3 forward,Vector3 normal){if(Paused||saveBlocked||Inventory[94]<1||InstalledCameras.Count>=16){Notice="不能安装：检查库存、存档或16个镜头的上限。";return false;}if(!CameraVectorValid(p)||normal.sqrMagnitude<.5f||forward.sqrMagnitude<.5f)return false;foreach(var c in InstalledCameras)if(c.region==World.Region&&Vector3.Distance(c.position,p)<.6f){Notice="这个位置已有摄像头，请换个地方。";return false;}int id=1;foreach(var c in InstalledCameras)id=Mathf.Max(id,c.id+1);Vector3 look=normal.y>.6f?Vector3.ProjectOnPlane(forward,Vector3.up):normal;if(look.sqrMagnitude<.1f)look=Vector3.forward;var data=new InstalledCamera{id=id,region=World.Region,realm=InVoidRealms,position=p,forward=look.normalized,normal=normal.normalized};InstalledCameras.Add(data);Inventory[94]--;try{WorldSave.Write(WorldSave.Capture(World,Player,Inventory,Selected),WorldSave.PathName);}catch(Exception){InstalledCameras.Remove(data);Inventory[94]++;Notice="安装没有保存，摄像头已退回背包。";return false;}BuildInstalledCameras();Notice="摄像头"+id+"已安装，密室显示屏已加入这个镜头。";return true;}
        public bool RemoveInstalledCamera(int id){InstalledCamera target=null;foreach(var c in InstalledCameras)if(c.id==id)target=c;if(target==null||saveBlocked||Inventory[94]>=9999)return false;int at=InstalledCameras.IndexOf(target);InstalledCameras.RemoveAt(at);Inventory[94]++;try{WorldSave.Write(WorldSave.Capture(World,Player,Inventory,Selected),WorldSave.PathName);}catch(Exception){InstalledCameras.Insert(at,target);Inventory[94]--;Notice="拆回没有保存，摄像头仍保留在原位置。";return false;}BuildInstalledCameras();Notice="摄像头已拆回背包。";return true;}
        static bool CameraVectorValid(Vector3 p)=>!float.IsNaN(p.x)&&!float.IsNaN(p.y)&&!float.IsNaN(p.z)&&!float.IsInfinity(p.x)&&!float.IsInfinity(p.y)&&!float.IsInfinity(p.z)&&Mathf.Abs(p.x)<10000&&Mathf.Abs(p.z)<10000&&p.y> -2000&&p.y<300;
        public static void ValidateInstalledCameras(SavedWorld s){if(s.cameraKitVersion<0||s.cameraKitVersion>1)throw new System.IO.InvalidDataException("摄像头礼包版本不合法");if(s.installedCameras==null)return;if(s.installedCameras.Count>16)throw new System.IO.InvalidDataException("摄像头太多");var ids=new HashSet<int>();foreach(var c in s.installedCameras)if(c==null||c.id<1||!ids.Add(c.id)||c.region<0||c.region>=VoxelWorld.RegionNames.Length||!CameraVectorValid(c.position)||!CameraVectorValid(c.forward)||!CameraVectorValid(c.normal)||c.forward.sqrMagnitude<.5f||c.forward.sqrMagnitude>1.1f||c.normal.sqrMagnitude<.5f||c.normal.sqrMagnitude>1.1f)throw new System.IO.InvalidDataException("摄像头安装记录不合法");}
        void BuildInstalledCameras(){if(installedCameraRoot!=null){installedCameraRoot.gameObject.SetActive(false);Destroy(installedCameraRoot.gameObject);}installedCameraRoot=new GameObject("玩家安装的摄像头").transform;installedCameraRoot.SetParent(villagePeople.transform,false);foreach(var c in InstalledCameras)if(c.region==World.Region){var root=new GameObject("安装镜头 "+c.id).transform;root.SetParent(installedCameraRoot,false);root.position=c.position;root.rotation=Quaternion.LookRotation(c.forward);var art=root.gameObject.AddComponent<RoyalArt>();art.Piece("摄像头底座",new Vector3(0,-.09f,-.1f),new Vector3(.35f,.15f,.28f),new Color(.42f,.5f,.57f),PrimitiveType.Cube,true);art.Piece("摄像头外壳",Vector3.zero,new Vector3(.42f,.25f,.38f),new Color(.88f,.91f,.92f),PrimitiveType.Cube,true);art.Piece("黑色镜头",new Vector3(0,0,.22f),new Vector3(.18f,.18f,.18f),new Color(.04f,.1f,.14f),PrimitiveType.Sphere);art.Piece("蓝色镜片",new Vector3(0,0,.31f),new Vector3(.12f,.12f,.02f),new Color(.3f,.8f,1));art.Piece("工作指示灯",new Vector3(.14f,.075f,.2f),Vector3.one*.035f,new Color(.3f,1,.55f),PrimitiveType.Sphere);root.gameObject.AddComponent<CameraFixture>().Data=c;}}
    }
}
